from taf.collectors.core import StartableCommandCollector
import six
from abc import ABCMeta, abstractmethod


@six.add_metaclass(ABCMeta)
class KubernetesCollector(StartableCommandCollector):
    """
    To collect kubernetes logs from controller.
    """

    def __init__(self, pod_name, namespace, target_file_name="kubernetes_log.tgz", **kwargs):
        super(KubernetesCollector, self).__init__(**kwargs)
        self._pod_name = pod_name
        self._namespace = namespace
        self._tmp_log_dir = "/tmp/kubernetes_{name}".format(name=self._name)
        self._target_file_name = target_file_name
        self._start_time = None
        self._stop_time = None

    def _start(self):
        self._start_time = self._tool_executor.execute('date -u +"%Y-%m-%dT%H:%M:%S.%NZ"').decode().strip()

    def _stop(self):
        self._stop_time = self._tool_executor.execute('date -u +"%Y-%m-%dT%H:%M:%S.%NZ"').decode().strip()

    def _setup(self):
        self._sudo_prefix = self._tool_executor.sudo_prefix()
        self._tool_executor.execute("rm -rf '{tmp_log_dir}'".format(tmp_log_dir=self._tmp_log_dir))
        self._tool_executor.execute("mkdir -p '{tmp_log_dir}'".format(tmp_log_dir=self._tmp_log_dir))

    def _teardown(self):
        self._tool_executor.execute("rm -rf '{tmp_log_dir}'".format(tmp_log_dir=self._tmp_log_dir))

    def _tar_files(self, executor, target_dir):
        executor.execute("cd '{target_dir}'; rm -f *.tgz; tar czf '{target_file_name}' *".format(
            target_dir=target_dir, target_file_name=self._target_file_name))

    @abstractmethod
    def _generate_logs(self):
        pass

    def _generate_and_pack_logs(self):
        self._generate_logs()
        self._tar_files(self._tool_executor, self._tmp_log_dir)

    def _collect(self, target_dir):
        self._generate_and_pack_logs()
        self._file_getter.get_file(source_path=self._tmp_log_dir + '/' + self._target_file_name,
                                   target_path=target_dir + '/' + self._target_file_name)


class PodCollector(KubernetesCollector):
    def _generate_logs(self):
        tmp_log_path = "{tmp_log_dir}/{pod_name}.log".format(
            tmp_log_dir=self._tmp_log_dir,
            pod_name=self._pod_name)
        fetch_log_entries_after_start_time = \
            "kubectl logs {pod_name} -n {namespace} --all-containers --since-time={start_time} --timestamps".format(
                pod_name=self._pod_name,
                namespace=self._namespace,
                start_time=self._start_time)
        skip_log_entries_after_stop_time = \
            "perl -lape'exit if $F[0] gt \"{stop_time}\"'".format(
                stop_time=self._stop_time)
        self._tool_executor.execute(
            "{fetch_log_entries_after_start_time} | {skip_log_entries_after_stop_time} > '{tmp_log_path}'".format(
                fetch_log_entries_after_start_time=fetch_log_entries_after_start_time,
                skip_log_entries_after_stop_time=skip_log_entries_after_stop_time,
                tmp_log_path=tmp_log_path))


class ContainerCollector(KubernetesCollector):
    def __init__(self, **kwargs):
        super(ContainerCollector, self).__init__(**kwargs)
        self._container = None

    def _generate_logs(self):
        for container in self._containers:
            tmp_log_path = "{tmp_log_dir}/{container}.log".format(
                tmp_log_dir=self._tmp_log_dir,
                container=container)
            fetch_log_entries_after_start_time = \
                "kubectl logs {pod_name} -n {namespace} -c {container} --since-time={start_time} --timestamps".format(
                    pod_name=self._pod_name,
                    namespace=self._namespace,
                    container=container,
                    start_time=self._start_time)
            skip_log_entries_after_stop_time = \
                "perl -lape'exit if $F[0] gt \"{stop_time}\"'".format(
                    stop_time=self._stop_time)
            self._tool_executor.execute(
                "{fetch_log_entries_after_start_time} | {skip_log_entries_after_stop_time} > '{tmp_log_path}'".format(
                    fetch_log_entries_after_start_time=fetch_log_entries_after_start_time,
                    skip_log_entries_after_stop_time=skip_log_entries_after_stop_time,
                    tmp_log_path=tmp_log_path))


class SingleContainerCollector(ContainerCollector):
    def __init__(self, container, **kwargs):
        super(SingleContainerCollector, self).__init__(**kwargs)
        self._containers = [container]


class MultiContainerCollector(ContainerCollector):
    def _setup(self):
        super(MultiContainerCollector, self)._setup()
        self._containers = self._get_all_containers_of_pod()

    def _get_all_containers_of_pod(self):
        cmd = "kubectl get pods -n {namespace} {pod_name} " \
              "-o jsonpath='{{range .spec.containers[*]}}{{.name}}{{\"\\n\"}}{{end}}'" \
            .format(namespace=self._namespace, pod_name=self._pod_name)
        output = self._tool_executor.execute(cmd, use_tty=True)
        containers = [container.rstrip() for container in output.decode().split("\n") if container]
        return containers
